// Switchable launcher icons (Settings → App icon), the way Telegram forks do it: MainActivity loses its launcher
// intent filter and every icon variant becomes an <activity-alias> of it with its own icon. Exactly one alias is
// enabled at a time; modules/app-icon flips them with PackageManager.setComponentEnabledSetting.
// Variants and artwork come from assets/app-icons (generated by tools/brand/build-icons.ts). The first variant is the
// default and uses the regular Expo icon resources. Never rename or remove an alias: a disabled default plus a missing
// chosen alias would leave the app without a launcher entry.
const { AndroidConfig, withAndroidManifest, withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const VARIANTS = require('../assets/app-icons/variants.json');
const DEFAULT = VARIANTS[0].id;
const res = (id) => `app_icon_${id}`;

function withIconAliases(config) {
  return withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);
    const main = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    const isLauncher = (f) =>
      (f.action ?? []).some((a) => a.$['android:name'] === 'android.intent.action.MAIN') &&
      (f.category ?? []).some((c) => c.$['android:name'] === 'android.intent.category.LAUNCHER');
    main['intent-filter'] = (main['intent-filter'] ?? []).filter((f) => !isLauncher(f));

    app['activity-alias'] = (app['activity-alias'] ?? []).filter((a) => !a.$['android:name'].startsWith('.AppIcon_'));
    for (const { id } of VARIANTS) {
      const icon = id === DEFAULT ? '@mipmap/ic_launcher' : `@mipmap/${res(id)}`;
      app['activity-alias'].push({
        $: {
          'android:name': `.AppIcon_${id}`,
          'android:targetActivity': '.MainActivity',
          'android:enabled': String(id === DEFAULT),
          'android:exported': 'true',
          'android:icon': icon,
          'android:roundIcon': id === DEFAULT ? '@mipmap/ic_launcher_round' : icon,
          'android:label': '@string/app_name',
        },
        'intent-filter': [
          {
            action: [{ $: { 'android:name': 'android.intent.action.MAIN' } }],
            category: [{ $: { 'android:name': 'android.intent.category.LAUNCHER' } }],
          },
        ],
      });
    }
    return cfg;
  });
}

const adaptive = (id) => `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@drawable/${res(id)}_bg"/>
    <foreground android:drawable="@drawable/${res(id)}_fg"/>
    <monochrome android:drawable="@mipmap/ic_launcher_monochrome"/>
</adaptive-icon>
`;

function withIconResources(config) {
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const src = path.join(cfg.modRequest.projectRoot, 'assets/app-icons');
      const out = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res');
      const dir = (d) => {
        fs.mkdirSync(path.join(out, d), { recursive: true });
        return path.join(out, d);
      };
      for (const { id } of VARIANTS) {
        if (id === DEFAULT) continue;
        fs.copyFileSync(path.join(src, `android/${id}-bg.png`), path.join(dir('drawable-nodpi'), `${res(id)}_bg.png`));
        fs.copyFileSync(path.join(src, `android/${id}-fg.png`), path.join(dir('drawable-nodpi'), `${res(id)}_fg.png`));
        fs.writeFileSync(path.join(dir('mipmap-anydpi-v26'), `${res(id)}.xml`), adaptive(id));
        // Pre-Android 8 launchers: the flat preview.
        fs.copyFileSync(path.join(src, `${id}.png`), path.join(dir('mipmap-xxxhdpi'), `${res(id)}.png`));
      }
      return cfg;
    },
  ]);
}

module.exports = function withAppIcons(config) {
  return withIconResources(withIconAliases(config));
};
